<div class="adminhead"><h1>علوم و دسته‌بندی‌ها</h1><a href="/admin">داشبورد</a></div><form class="formbox compact" method="post" action="/admin/category/save"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($editing['id']??0)?>"><div class="two"><input name="name" required placeholder="نام دسته جدید" value="<?=e($editing['name']??'')?>"><select name="section"><option value="science" <?=($editing['section']??'science')==='science'?'selected':''?>>علوم</option><option value="curriculum" <?=($editing['section']??'')==='curriculum'?'selected':''?>>فنون درسی</option><option value="school" <?=($editing['section']??'')==='school'?'selected':''?>>کتاب‌های مکتب</option><option value="school_subject" <?=($editing['section']??'')==='school_subject'?'selected':''?>>مضمون مکتب</option><option value="modern" <?=($editing['section']??'')==='modern'?'selected':''?>>علوم عصری</option></select><select name="parent_id"><option value="0">بدون والد</option><?php foreach($parents as $p):?><option value="<?=$p['id']?>" <?=((int)($editing['parent_id']??0)===(int)$p['id'])?'selected':''?>><?=e($p['name'])?> — <?=e($p['section'])?></option><?php endforeach;?></select><input type="number" name="sort_order" value="<?=e($editing['sort_order']??0)?>" placeholder="ترتیب"></div><label><input type="checkbox" name="active" <?=(!isset($editing)||!empty($editing['active']))?'checked':''?>> فعال در سایت</label><button><?=isset($editing)?'ذخیره ویرایش':'افزودن دسته'?></button></form><div class="table"><div class="thead"><span>نام</span><span>بخش</span><span>والد</span><span>ترتیب</span><span>عملیات</span></div><?php foreach($rows as $r):?><div class="tr"><span><?=e($r['name'])?></span><span><?=e($r['section'])?></span><span><?=e($r['parent']??'ریشه')?></span><span><?=e($r['sort_order'])?></span><span><a href="/admin/categories?edit=<?=$r['id']?>">ویرایش</a> <form class="inline" method="post" action="/admin/category/delete" onsubmit="return confirm('این دسته حذف شود؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button>حذف</button></form></span></div><?php endforeach;?></div>
